// When a plan change takes effect; `none` for anything that is not a change. A `period_end` order
// stays pending until the first period at the new price is paid. That period is invoiced when the
// order is created and starts when the current paid period ends; if the invoice is unpaid by then, the
// order is canceled and the item renews or ends with its subscription as usual.
type OrderChangeEffective string

const (
	OrderChangeEffectiveNone      OrderChangeEffective = "none"
	OrderChangeEffectiveImmediate OrderChangeEffective = "immediate"
	OrderChangeEffectivePeriodEnd OrderChangeEffective = "period_end"
)

// AllValues returns all OrderChangeEffective values.
func (OrderChangeEffective) AllValues() []OrderChangeEffective {
	return []OrderChangeEffective{
		OrderChangeEffectiveNone,
		OrderChangeEffectiveImmediate,
		OrderChangeEffectivePeriodEnd,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s OrderChangeEffective) MarshalText() ([]byte, error) {
	switch s {
	case OrderChangeEffectiveNone:
		return []byte(s), nil
	case OrderChangeEffectiveImmediate:
		return []byte(s), nil
	case OrderChangeEffectivePeriodEnd:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *OrderChangeEffective) UnmarshalText(data []byte) error {
	switch OrderChangeEffective(data) {
	case OrderChangeEffectiveNone:
		*s = OrderChangeEffectiveNone
		return nil
	case OrderChangeEffectiveImmediate:
		*s = OrderChangeEffectiveImmediate
		return nil
	case OrderChangeEffectivePeriodEnd:
		*s = OrderChangeEffectivePeriodEnd
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

// The purchase terms frozen at placement. Monetary fields come from the order's invoice lines and are
// zero without an immediate charge, such as for a metered purchase. Later catalog changes do not
// reprice the line. A new service purchase has its pending subscription and subscription item from
// placement.
// Ref: #/components/schemas/OrderItem
type OrderItem struct {
	// Whether new account discounts may apply to future renewals. A fixed operator renewal agreement
	// disables automatic discounts; catalog repricing or a newly selected purchase agreement enables them.
	RenewalDiscountsEnabled OptBool `json:"renewal_discounts_enabled"`
	// Financial lines produced by this purchase item, including setup charges.
	InvoiceItemIds []uuid.UUID               `json:"invoice_item_ids"`
	Position       OptInt                    `json:"position"`
	Configuration  OptOrderItemConfiguration `json:"configuration"`
	// The Billing subscription the line belongs to: a new pending one, the existing one an added item
	// joins, or the one renewed or changed, which keeps its ID. Absent for a purchase without a
	// subscription.
	SubscriptionID OptUUID `json:"subscription_id"`
	// The subscription item the line created, renewed or changed, which keeps its ID. Absent for a
	// purchase without a subscription.
	SubscriptionItemID OptUUID               `json:"subscription_item_id"`
	Interval           OrderItemInterval     `json:"interval"`
	IntervalCount      OptInt                `json:"interval_count"`
	CancellationPolicy OptCancellationPolicy `json:"cancellation_policy"`
	RefundPolicy       OptRefundPolicy       `json:"refund_policy"`
	// Recurring licensed items only: the reference list amount for one list_interval, for this item's
	// quantity and dimensions, in the order currency before tax and discounts. For monthly or yearly
	// purchases it is the monthly amount of the shortest eligible monthly or yearly price; for daily
	// purchases it is the daily amount of the shortest eligible daily price. Eligible prices belong to the
	// same plan, are sellable at purchase, and do not exceed the purchased period. The purchased price
	// itself is a candidate. Frozen at purchase; renewal at the agreed amount preserves it. Absent or null
	// when used time is valued proportionally at the amount paid.
	ListAmount OptNilString `json:"list_amount"`
	// Unit of the frozen list_amount. Present exactly when list_amount has a value; uses Billing's
	// interval vocabulary. It is the reference price unit, not necessarily the purchased period unit.
	ListInterval OptOrderItemListInterval `json:"list_interval"`
	// Refund policy `short_rate` only, as on the price when bought.
	ShortRateMultiplier OptNilString `json:"short_rate_multiplier"`
	// Refund policy `short_rate` only, as on the price when bought.
	ShortRateThresholdSeconds OptNilInt64 `json:"short_rate_threshold_seconds"`
	RecurringAmount           OptString   `json:"recurring_amount"`
	SetupAmount               OptString   `json:"setup_amount"`
	Type                      PriceType   `json:"type"`
	UsageType                 UsageType   `json:"usage_type"`
	// The dimension values the line was bought with, such as region and instance type. Empty when the
	// purchase gave none.
	Dimensions OrderItemDimensions `json:"dimensions"`
	// Total tax after discounts, including any tax already included in the price.
	TaxAmount OptString `json:"tax_amount"`
	// The part of tax_amount already included in gross_amount; it is not charged again.
	TaxIncludedAmount OptString `json:"tax_included_amount"`
	ID                uuid.UUID `json:"id"`
	OrderID           OptUUID   `json:"order_id"`
	PriceID           uuid.UUID `json:"price_id"`
	// Which service this line belongs to.
	ProductID OptProductId `json:"product_id"`
	Product   OptProduct   `json:"product"`
	// Which plan was bought.
	PlanID uuid.UUID `json:"plan_id"`
	// The name when bought.
	PlanName string `json:"plan_name"`
	Quantity string `json:"quantity"`
	// The plan's unit label when the line was placed, which a licensed line's quantity counts, such as GiB
	// or Mbps. Absent for a metered line and when the plan had none.
	UnitLabel OptString `json:"unit_label"`
	// The unit amount of the price the line is charged under. Absent for a tiered price, and for an
	// immediate change, which is charged as `gross_amount` describes.
	UnitAmount OptMoney `json:"unit_amount"`
	// Before discounts and setup fees: the price applied to the quantity, `unit_amount` times `quantity`
	// for a per- unit price, raised by any minimum charge. For an immediate upgrade it is the new price
	// for the rest of the paid period minus the amount paid for that time; a downgrade, or a change
	// between equal period prices, charges nothing.
	//
	// Under an inclusive tax rate it includes tax, shown in `tax_included_amount`, except for a renewal at
	// agreed terms, whose amount excludes tax.
	GrossAmount OptMoney `json:"gross_amount"`
	// The reduction on this line, from the order's coupon and, for a renewal at agreed terms, from the
	// subscription's carried discount. With a carried discount, `gross_amount` is `unit_amount` times
	// `quantity`, except when the renewal order also uses an account coupon or the tax rate is inclusive:
	// then `gross_amount` is the agreed amount, which already reflects the carried discount.
	DiscountAmount OptMoney `json:"discount_amount"`
	// `gross_amount` less `discount_amount`.
	Amount   OptMoney `json:"amount"`
	Currency string   `json:"currency"`
	// The start of the service period this line paid for. Fixed at placement for renewals and period-end
	// changes, and for a licensed line of a new purchase when its invoice is paid. Absent for metered and
	// one-time lines.
	PeriodStart OptNilDateTime `json:"period_start"`
	// The end of that service period, exclusive.
	PeriodEnd OptNilDateTime  `json:"period_end"`
	Status    OrderItemStatus `json:"status"`
}

