// Why the refund was made. New codes may be added; treat an unknown code as unspecified.
//
//   - `provisioning_failed`: the purchase could not be delivered.
//   - `order_expired`: the order expired after part of it was paid.
//   - `order_canceled`: the order was canceled after part of it was paid.
//   - `change_canceled`: a scheduled change was withdrawn after part of it was paid.
//   - `change_expired`: a scheduled change could not take effect in time.
//   - `subscription_canceled`: the unused value of a canceled subscription item, under its refund
//     terms.
//   - `future_period_canceled`: a renewal that had not started was withdrawn.
//   - `downgrade_difference`: after a downgrade, the remaining paid value, valued under each paid
//     period's refund policy and as `prorated` where that policy is `none`, minus the new
//     configuration's value for the remaining time: each complete `list_interval` at the change item's
//     `list_amount` and the remainder in proportion to the length of the reference interval it falls
//     in, or without `list_amount`, the new period price in proportion to the remaining time.
//   - `usage_true_up`: usage priced over the whole month cost less than was charged.
//   - `payment_not_applied`: a payment arrived after its invoice could no longer be paid.
//   - `operator`: made by the platform operator.
//
// Ref: #/components/schemas/RefundReason
type RefundReason string

const (
	RefundReasonProvisioningFailed   RefundReason = "provisioning_failed"
	RefundReasonOrderExpired         RefundReason = "order_expired"
	RefundReasonOrderCanceled        RefundReason = "order_canceled"
	RefundReasonChangeCanceled       RefundReason = "change_canceled"
	RefundReasonChangeExpired        RefundReason = "change_expired"
	RefundReasonSubscriptionCanceled RefundReason = "subscription_canceled"
	RefundReasonFuturePeriodCanceled RefundReason = "future_period_canceled"
	RefundReasonDowngradeDifference  RefundReason = "downgrade_difference"
	RefundReasonUsageTrueUp          RefundReason = "usage_true_up"
	RefundReasonPaymentNotApplied    RefundReason = "payment_not_applied"
	RefundReasonOperator             RefundReason = "operator"
)

